actions.script:
const counted = {open: caseCounts.openCount, overdue: caseCounts.overdueCount, unassigned: caseCounts.unassignedCount}
const queueText = (caseCounts.queueRows || []).length + ' ' + ec.l10n.localize('queues') + ', ' + ec.l10n.localize('now')
for (const measure of measures) if (Object.hasOwn(counted, measure.key))
    Object.assign(measure, {configured: true, valueText: String(counted[measure.key] ?? 0), denominatorText: queueText})

const levels = ec.resource.script('component://mr-boss/service/ironstone/customerservice/Cases.js').execute('slaMeasures', {periodDays: days})
if (levels.configured) for (const measure of measures) if (levels[measure.key])
    Object.assign(measure, levels[measure.key])
